// Emitters for errors.yaml: TypeScript, Go and Rust. The catalog order is preserved so a
// diff of the generated files reads like a diff of errors.yaml.
import { padTo, pascal, pascalGo, quote, quoteTs } from "../naming.mjs";

const SOURCE = "packages/contracts/errors.yaml";
const REGEN = "Regenerate with `make -C packages/contracts gen`.";
const FALLBACK = "internal_error";

function fallbackSpec(errors) {
  const spec = errors.byCode.get(FALLBACK);
  if (!spec) throw new Error(`errors.yaml precisa definir o código ${FALLBACK} (usado como fallback)`);
  return spec;
}

// ------------------------------------------------------------------------------ TypeScript

export function emitErrorsTs(errors) {
  fallbackSpec(errors);
  const lines = [];
  lines.push(`// Code generated by tools/codegen from ${SOURCE}. DO NOT EDIT.`);
  lines.push(`// ${REGEN}`);
  lines.push("");
  lines.push("/** Error categories (errors.yaml `categories`). */");
  lines.push("export type ErrorCategory =");
  errors.categories.forEach((c, i) => lines.push(`  | ${quoteTs(c.name)}${i === errors.categories.length - 1 ? ";" : ""}`));
  lines.push("");
  lines.push("/** HTTP status, category and the pt-BR message shown to the user. */");
  lines.push("export interface ErrorSpec {");
  lines.push("  readonly status: number;");
  lines.push("  readonly category: ErrorCategory;");
  lines.push("  readonly message: string;");
  lines.push("  /** The same request can be repeated unchanged after a short wait. */");
  lines.push("  readonly retryable: boolean;");
  lines.push("}");
  lines.push("");
  lines.push(`/** Error catalog (errors.yaml, version ${errors.version}), keyed by stable snake_case code. */`);
  lines.push("export const ERRORS = {");
  for (const e of errors.errors) {
    lines.push(
      `  ${e.code}: { status: ${e.status}, category: ${quoteTs(e.category)}, message: ${quoteTs(e.message)}, retryable: ${e.retryable} },`,
    );
  }
  lines.push("} as const satisfies Record<string, ErrorSpec>;");
  lines.push("");
  lines.push("export type ErrorCode = keyof typeof ERRORS;");
  lines.push("");
  lines.push("/** Every code, in catalog order. */");
  lines.push("export const ERROR_CODES: readonly ErrorCode[] = Object.keys(ERRORS) as ErrorCode[];");
  lines.push("");
  lines.push("export function isErrorCode(value: unknown): value is ErrorCode {");
  lines.push("  return typeof value === 'string' && Object.hasOwn(ERRORS, value);");
  lines.push("}");
  lines.push("");
  lines.push(`/** Spec for a code; unknown codes fall back to \`${FALLBACK}\`. */`);
  lines.push("export function errorSpec(code: string): ErrorSpec {");
  lines.push(`  return isErrorCode(code) ? ERRORS[code] : ERRORS.${FALLBACK};`);
  lines.push("}");
  lines.push("");
  lines.push("/** Error envelope returned by every endpoint (schema `Error` in openapi.yaml). */");
  lines.push("export interface ErrorEnvelope {");
  lines.push("  code: ErrorCode;");
  lines.push("  message: string;");
  lines.push("  request_id: string;");
  lines.push("  details?: Record<string, unknown>;");
  lines.push("}");
  return `${lines.join("\n")}\n`;
}

// ------------------------------------------------------------------------------ Go

export function goErrorName(code) {
  return `Err${pascalGo(code)}`;
}

function goCategoryName(category) {
  return `ErrorCategory${pascalGo(category)}`;
}

export function emitErrorsGo(errors) {
  const fallback = fallbackSpec(errors);
  const lines = [];
  lines.push(`// Code generated by tools/codegen from ${SOURCE}. DO NOT EDIT.`);
  lines.push("");
  lines.push("package contracts");
  lines.push("");
  lines.push("// ErrorCode is a stable snake_case code from errors.yaml, sent in the error envelope.");
  lines.push("type ErrorCode string");
  lines.push("");
  lines.push("// ErrorCategory groups codes (errors.yaml `categories`).");
  lines.push("type ErrorCategory string");
  lines.push("");
  lines.push("// Error categories.");
  lines.push("const (");
  {
    const names = errors.categories.map((c) => goCategoryName(c.name));
    const width = Math.max(...names.map((n) => n.length));
    errors.categories.forEach((c, i) => lines.push(`\t${padTo(names[i], width)} ErrorCategory = ${quote(c.name)}`));
  }
  lines.push(")");
  lines.push("");
  lines.push(`// Error codes (errors.yaml, version ${errors.version}).`);
  lines.push("const (");
  {
    const names = errors.errors.map((e) => goErrorName(e.code));
    const width = Math.max(...names.map((n) => n.length));
    errors.errors.forEach((e, i) => lines.push(`\t${padTo(names[i], width)} ErrorCode = ${quote(e.code)}`));
  }
  lines.push(")");
  lines.push("");
  lines.push("// ErrorSpec is the HTTP status, the category and the pt-BR message of a code.");
  lines.push("type ErrorSpec struct {");
  lines.push("\tCode     ErrorCode");
  lines.push("\tStatus   int");
  lines.push("\tCategory ErrorCategory");
  lines.push("\t// Message is shown to the user as is.");
  lines.push("\tMessage string");
  lines.push("\t// Retryable means the same request can be repeated unchanged after a short wait.");
  lines.push("\tRetryable bool");
  lines.push("}");
  lines.push("");
  lines.push("// ErrorCodes lists every code in catalog order.");
  lines.push("var ErrorCodes = []ErrorCode{");
  for (const e of errors.errors) lines.push(`\t${goErrorName(e.code)},`);
  lines.push("}");
  lines.push("");
  lines.push("// ErrorSpecs maps every code to its spec.");
  lines.push("var ErrorSpecs = map[ErrorCode]ErrorSpec{");
  {
    const keys = errors.errors.map((e) => `${goErrorName(e.code)}:`);
    const width = Math.max(...keys.map((k) => k.length)) + 1;
    errors.errors.forEach((e, i) => {
      lines.push(
        `\t${padTo(keys[i], width)}{Code: ${goErrorName(e.code)}, Status: ${e.status}, Category: ${goCategoryName(e.category)}, Message: ${quote(e.message)}, Retryable: ${e.retryable}},`,
      );
    });
  }
  lines.push("}");
  lines.push("");
  lines.push("// Spec returns the spec of the code; ok is false for unknown codes.");
  lines.push("func (c ErrorCode) Spec() (spec ErrorSpec, ok bool) {");
  lines.push("\tspec, ok = ErrorSpecs[c]");
  lines.push("\treturn spec, ok");
  lines.push("}");
  lines.push("");
  lines.push(`// Status returns the HTTP status of the code, ${fallback.status} for unknown codes.`);
  lines.push("func (c ErrorCode) Status() int {");
  lines.push("\tif spec, ok := ErrorSpecs[c]; ok {");
  lines.push("\t\treturn spec.Status");
  lines.push("\t}");
  lines.push(`\treturn ErrorSpecs[${goErrorName(FALLBACK)}].Status`);
  lines.push("}");
  lines.push("");
  lines.push(`// Message returns the pt-BR message of the code, the ${FALLBACK} message for unknown codes.`);
  lines.push("func (c ErrorCode) Message() string {");
  lines.push("\tif spec, ok := ErrorSpecs[c]; ok {");
  lines.push("\t\treturn spec.Message");
  lines.push("\t}");
  lines.push(`\treturn ErrorSpecs[${goErrorName(FALLBACK)}].Message`);
  lines.push("}");
  lines.push("");
  lines.push("// Category returns the category of the code; empty for unknown codes.");
  lines.push("func (c ErrorCode) Category() ErrorCategory {");
  lines.push("\treturn ErrorSpecs[c].Category");
  lines.push("}");
  lines.push("");
  lines.push("// Retryable reports whether the same request can be repeated unchanged after a short wait.");
  lines.push("func (c ErrorCode) Retryable() bool {");
  lines.push("\treturn ErrorSpecs[c].Retryable");
  lines.push("}");
  lines.push("");
  lines.push("// Known reports whether the code exists in the catalog.");
  lines.push("func (c ErrorCode) Known() bool {");
  lines.push("\t_, ok := ErrorSpecs[c]");
  lines.push("\treturn ok");
  lines.push("}");
  lines.push("");
  lines.push("// String implements fmt.Stringer.");
  lines.push("func (c ErrorCode) String() string {");
  lines.push("\treturn string(c)");
  lines.push("}");
  return `${lines.join("\n")}\n`;
}

// ------------------------------------------------------------------------------ Rust

const RUST_MAX_WIDTH = 100;

export function rustVariant(code) {
  return pascal(code);
}

// A match arm; rustfmt moves the expression into a block when the one-line form is too long.
function rustArm(indent, pattern, expr, lines) {
  const one = `${indent}${pattern} => ${expr},`;
  if (one.length <= RUST_MAX_WIDTH) {
    lines.push(one);
    return;
  }
  lines.push(`${indent}${pattern} => {`);
  lines.push(`${indent}    ${expr}`);
  lines.push(`${indent}}`);
}

export function emitErrorsRs(errors) {
  const fallback = fallbackSpec(errors);
  const lines = [];
  lines.push(`//! Code generated by tools/codegen from ${SOURCE}. DO NOT EDIT.`);
  lines.push("//!");
  lines.push(`//! Error catalog (errors.yaml, version ${errors.version}): stable codes, HTTP status and the`);
  lines.push("//! pt-BR message shown to the user. No dependencies; serde impls belong to the consumer.");
  lines.push("");
  lines.push("/// Error categories (errors.yaml `categories`).");
  lines.push("#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]");
  lines.push("pub enum ErrorCategory {");
  for (const c of errors.categories) {
    lines.push(`    /// ${c.description}`);
    lines.push(`    ${pascal(c.name)},`);
  }
  lines.push("}");
  lines.push("");
  lines.push("impl ErrorCategory {");
  lines.push("    /// The snake_case name used in errors.yaml.");
  lines.push("    pub const fn as_str(self) -> &'static str {");
  lines.push("        match self {");
  for (const c of errors.categories) rustArm("            ", `ErrorCategory::${pascal(c.name)}`, quote(c.name), lines);
  lines.push("        }");
  lines.push("    }");
  lines.push("}");
  lines.push("");
  lines.push("/// Stable error code from errors.yaml, sent in the error envelope.");
  lines.push("#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]");
  lines.push("pub enum ErrorCode {");
  for (const e of errors.errors) {
    lines.push(`    /// \`${e.code}\` (${e.status})`);
    lines.push(`    ${rustVariant(e.code)},`);
  }
  lines.push("}");
  lines.push("");
  lines.push("/// Error returned when parsing an unknown code.");
  lines.push("#[derive(Debug, Clone, PartialEq, Eq)]");
  lines.push("pub struct UnknownErrorCode(pub String);");
  lines.push("");
  lines.push("impl core::fmt::Display for UnknownErrorCode {");
  lines.push("    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {");
  lines.push('        write!(f, "unknown error code: {}", self.0)');
  lines.push("    }");
  lines.push("}");
  lines.push("");
  lines.push("impl std::error::Error for UnknownErrorCode {}");
  lines.push("");
  lines.push("impl ErrorCode {");
  lines.push("    /// Every code, in catalog order.");
  lines.push("    pub const ALL: &'static [ErrorCode] = &[");
  for (const e of errors.errors) lines.push(`        ErrorCode::${rustVariant(e.code)},`);
  lines.push("    ];");
  lines.push("");
  lines.push(`    /// Code used when a message cannot be mapped (\`${FALLBACK}\`).`);
  lines.push(`    pub const FALLBACK: ErrorCode = ErrorCode::${rustVariant(FALLBACK)};`);
  lines.push("");
  lines.push("    /// The snake_case code sent in the error envelope.");
  lines.push("    pub const fn as_str(self) -> &'static str {");
  lines.push("        match self {");
  for (const e of errors.errors) rustArm("            ", `ErrorCode::${rustVariant(e.code)}`, quote(e.code), lines);
  lines.push("        }");
  lines.push("    }");
  lines.push("");
  lines.push(`    /// HTTP status of the code (${fallback.status} for \`${FALLBACK}\`).`);
  lines.push("    pub const fn http_status(self) -> u16 {");
  lines.push("        match self {");
  for (const e of errors.errors) rustArm("            ", `ErrorCode::${rustVariant(e.code)}`, String(e.status), lines);
  lines.push("        }");
  lines.push("    }");
  lines.push("");
  lines.push("    /// Category of the code.");
  lines.push("    pub const fn category(self) -> ErrorCategory {");
  lines.push("        match self {");
  for (const e of errors.errors) {
    rustArm("            ", `ErrorCode::${rustVariant(e.code)}`, `ErrorCategory::${pascal(e.category)}`, lines);
  }
  lines.push("        }");
  lines.push("    }");
  lines.push("");
  lines.push("    /// pt-BR message shown to the user.");
  lines.push("    pub const fn message(self) -> &'static str {");
  lines.push("        match self {");
  for (const e of errors.errors) rustArm("            ", `ErrorCode::${rustVariant(e.code)}`, quote(e.message), lines);
  lines.push("        }");
  lines.push("    }");
  lines.push("");
  lines.push("    /// True when the same request can be repeated unchanged after a short wait.");
  lines.push("    pub const fn retryable(self) -> bool {");
  const retryable = errors.errors.filter((e) => e.retryable);
  if (retryable.length === 0) {
    lines.push("        false");
  } else {
    lines.push("        matches!(");
    lines.push("            self,");
    // rustfmt indents the `|` continuation of a multi-line or-pattern by four extra spaces.
    retryable.forEach((e, i) => {
      lines.push(i === 0 ? `            ErrorCode::${rustVariant(e.code)}` : `                | ErrorCode::${rustVariant(e.code)}`);
    });
    lines.push("        )");
  }
  lines.push("    }");
  lines.push("");
  lines.push("    /// Parses a snake_case code.");
  lines.push("    pub fn parse(code: &str) -> Option<ErrorCode> {");
  lines.push("        match code {");
  for (const e of errors.errors) rustArm("            ", quote(e.code), `Some(ErrorCode::${rustVariant(e.code)})`, lines);
  lines.push("            _ => None,");
  lines.push("        }");
  lines.push("    }");
  lines.push("}");
  lines.push("");
  lines.push("impl core::fmt::Display for ErrorCode {");
  lines.push("    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {");
  lines.push("        f.write_str(self.as_str())");
  lines.push("    }");
  lines.push("}");
  lines.push("");
  lines.push("impl core::str::FromStr for ErrorCode {");
  lines.push("    type Err = UnknownErrorCode;");
  lines.push("");
  lines.push("    fn from_str(code: &str) -> Result<Self, Self::Err> {");
  lines.push("        ErrorCode::parse(code).ok_or_else(|| UnknownErrorCode(code.to_owned()))");
  lines.push("    }");
  lines.push("}");
  return `${lines.join("\n")}\n`;
}
